def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "broadcast_announcement": And([
            self.match_active,
            self.robot_has_announcement(self.match_result),
            self.loudspeaker_available,
            self.match_schedule_known
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
